Task<Location> GetLocationAsync()
{
    var tcs = new TaskCompletionSource<Location>(
        TaskCreationOptions.RunContinuationsAsynchronously);
    gps.OnFix += loc => tcs.TrySetResult(loc);
    gps.OnError += e => tcs.TrySetException(e);
    gps.Start();
    return tcs.Task;
}

